package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class LmdbDirectAdjacencyIteratorTest {

	private LmdbAdjacencyArena arena;
	private LmdbAdjacencyArenaCatalog catalog;
	private LmdbAdjacencyContextCatalog contexts;
	private long handle;

	private static final long KEY = 77;
	private static final long PRED = 88;
	private static final long G1 = 500;
	private static final long G2 = 600;

	@BeforeEach
	void setUp() {
		arena = new LmdbAdjacencyArena(1 << 20);
		catalog = LmdbAdjacencyArenaCatalog.of(arena);
		contexts = LmdbAdjacencyContextCatalog.base(arena, new long[] { G1, G2 });
		long[][] pairs = { { 10, 0 }, { 10, G1 }, { 20, G2 }, { 30, 0 }, { 40, G1 } };
		long ref = LmdbAdjacencyRunCodec.encode(new SortedPairSource() {
			private int index = -1;

			@Override
			public boolean next() {
				return ++index < pairs.length;
			}

			@Override
			public long neighbor() {
				return pairs[index][0];
			}

			@Override
			public long context() {
				return pairs[index][1];
			}
		}, contexts, arena);
		handle = catalog.packHandle(0, ref);
	}

	@AfterEach
	void tearDown() {
		catalog.close();
		arena.close();
	}

	@Test
	void iteratesBothDirectionsWithUnboundContext() {
		LmdbDirectAdjacencyIterator iterator = new LmdbDirectAdjacencyIterator();
		iterator.init(null, catalog, contexts, handle, KEY, PRED, -1, LmdbDirectAdjacencyIterator.BY_SUBJECT, "direct");

		long[] quad = iterator.next();
		assertThat(quad[TripleIndex.SUBJ_IDX]).isEqualTo(KEY);
		assertThat(quad[TripleIndex.PRED_IDX]).isEqualTo(PRED);
		assertThat(quad[TripleIndex.OBJ_IDX]).isEqualTo(10);
		assertThat(quad[TripleIndex.CONTEXT_IDX]).isZero();
		int rows = 1;
		while (iterator.next() != null) {
			rows++;
		}
		assertThat(rows).isEqualTo(5);
		assertThat(iterator.getIndexName()).isEqualTo("direct");

		iterator.init(null, catalog, contexts, handle, KEY, PRED, -1, LmdbDirectAdjacencyIterator.BY_OBJECT, "");
		quad = iterator.next();
		assertThat(quad[TripleIndex.OBJ_IDX]).isEqualTo(KEY);
		assertThat(quad[TripleIndex.SUBJ_IDX]).isEqualTo(10);
	}

	@Test
	void boundContextFiltersExactly() {
		LmdbDirectAdjacencyIterator iterator = new LmdbDirectAdjacencyIterator();
		iterator.init(null, catalog, contexts, handle, KEY, PRED, G1, LmdbDirectAdjacencyIterator.BY_SUBJECT, "");
		assertThat(iterator.next()[TripleIndex.OBJ_IDX]).isEqualTo(10);
		assertThat(iterator.next()[TripleIndex.OBJ_IDX]).isEqualTo(40);
		assertThat(iterator.next()).isNull();

		// the null graph is context zero, exactly
		iterator.init(null, catalog, contexts, handle, KEY, PRED, 0, LmdbDirectAdjacencyIterator.BY_SUBJECT, "");
		assertThat(iterator.next()[TripleIndex.OBJ_IDX]).isEqualTo(10);
		assertThat(iterator.next()[TripleIndex.OBJ_IDX]).isEqualTo(30);
		assertThat(iterator.next()).isNull();

		// a bound context that the catalog has never seen proves emptiness without decoding
		iterator.init(null, catalog, contexts, handle, KEY, PRED, 999, LmdbDirectAdjacencyIterator.BY_SUBJECT, "");
		assertThat(iterator.next()).isNull();
	}

	@Test
	void fillMirrorsNextAndSeekUsesTheCodecLowerBound() {
		LmdbDirectAdjacencyIterator iterator = new LmdbDirectAdjacencyIterator();
		iterator.init(null, catalog, contexts, handle, KEY, PRED, -1, LmdbDirectAdjacencyIterator.BY_SUBJECT, "");
		long[] buffer = new long[4 * 8];
		assertThat(iterator.fill(buffer, 8)).isEqualTo(5);
		assertThat(buffer[TripleIndex.OBJ_IDX]).isEqualTo(10);
		assertThat(buffer[4 * 4 + TripleIndex.OBJ_IDX]).isEqualTo(40);

		iterator.init(null, catalog, contexts, handle, KEY, PRED, -1, LmdbDirectAdjacencyIterator.BY_SUBJECT, "");
		assertThat(iterator.seekForward(-1, PRED, 30, -1)).isTrue();
		assertThat(iterator.next()[TripleIndex.OBJ_IDX]).isEqualTo(30);
		assertThat(iterator.next()[TripleIndex.OBJ_IDX]).isEqualTo(40);
		assertThat(iterator.next()).isNull();
	}

	@Test
	void negativeHandleInitializesEmpty() {
		LmdbDirectAdjacencyIterator iterator = new LmdbDirectAdjacencyIterator();
		iterator.init(null, catalog, contexts, LmdbInMemoryAdjacencyIndex.NOT_FOUND, KEY, PRED, -1,
				LmdbDirectAdjacencyIterator.BY_SUBJECT, "");
		assertThat(iterator.next()).isNull();
		assertThat(iterator.fill(new long[8], 2)).isZero();
	}

	@Test
	void failedRetainAfterCloseDoesNotResurrectTheLeaseCounter() {
		LmdbAdjacencyReadView view = LmdbAdjacencyReadView.fallback(7,
				LmdbAdjacencyMetrics.FallbackReason.BUILDING);
		view.close();

		assertThatThrownBy(view::retainLease)
				.isInstanceOf(IllegalStateException.class)
				.hasMessageContaining("retained after close");
		assertThatThrownBy(view::close)
				.isInstanceOf(IllegalStateException.class)
				.hasMessageContaining("released more times than retained");
	}
}
